def read_cstr(addr_str, maxlen=48):
    addr = prog.getAddressFactory().getAddress(addr_str)
    mem = prog.getMemory()
    b = mem.getBytes(addr, maxlen)
    s = bytes(b)
    z = s.find(b"\x00")
    s = s[:z] if z != -1 else s
    return s.decode("utf-8", "replace")
